"""Where the SDK sends data, and how that is decided.

Every integration module used to carry its own hardcoded default, and seven of
the eight ignored the environment entirely -- so ``PRISMTRACE_HOST`` worked for
LangChain users and was silently dropped for everyone else. Worse, the default
they carried named the *staging* backend, which meant an installed-from-PyPI
user who did not pass ``endpoint=`` sent their traces to a database they could
not see, with nothing anywhere saying why.

Both problems are the same problem: the destination was decided in eight places
instead of one. It is decided here now.

Resolution order, highest priority first:

1. An explicit argument passed by the caller.
2. ``PRISMTRACE_HOST``, then ``PRISMTRACE_ENDPOINT``.
3. :data:`DEFAULT_HOST`.

The env layer is what makes a single installed package usable against staging,
a local stack, or a self-hosted deployment without a code change.
"""
from __future__ import annotations

import os
from typing import Optional

#: Production API. A custom domain rather than the Railway hostname on purpose:
#: it is the address we control, so moving providers does not strand every
#: installed copy of the SDK on a hostname we no longer own.
#:
#: Its TLS certificate renews through the ``_railway-verify.api.prism`` TXT
#: record in the blockconvey.com zone. That record must stay in place.
DEFAULT_HOST = "https://api.prism.blockconvey.com"

#: Checked in order, first non-empty wins.
_ENV_VARS = ("PRISMTRACE_HOST", "PRISMTRACE_ENDPOINT")


def resolve_host(*candidates: Optional[str]) -> str:
    """Return the base URL to send to, without a trailing slash.

    Accepts several candidates so callers that expose both ``host=`` and
    ``endpoint=`` can pass them in priority order. Empty strings and
    whitespace-only values are treated as absent: an unset shell variable
    commonly arrives as ``""``, and silently sending to ``""`` is worse than
    falling through to the default.
    """
    for candidate in candidates:
        if candidate and str(candidate).strip():
            return str(candidate).strip().rstrip("/")

    for var in _ENV_VARS:
        value = os.getenv(var)
        if value and value.strip():
            return value.strip().rstrip("/")

    return DEFAULT_HOST
